import type * as React from "react";

export type ComponentRenderFn<Props, State> = (
  props: Props,
  state: State
) => React.ReactElement<unknown>;

export type HTMLProps = React.HTMLAttributes<any> & {
  ref?: React.Ref<any> | undefined;
};

/**
 * Headless-library props mixin: element props plus an anonymous `{ render?: … }`
 * member, the Base UI `useRender.ComponentProps` shape.
 */
export type ComponentProps<ElementType extends React.ElementType> = React.ComponentPropsWithRef<ElementType> & {
  /**
   * Replaces the rendered element.
   */
  render?: React.ReactElement | ComponentRenderFn<HTMLProps, Record<string, never>> | undefined;
};
